import json, subprocess, sys

# Load current flow
with open('/work/output/artifacts/skill-flow-slack-weather-pipeline/SlackWeatherPipeline/SlackWeatherPipeline/SlackWeatherPipeline.flow') as f:
    flow = json.load(f)

# Get full definitions from registry
def get_def(node_type):
    r = subprocess.run(['uip', 'maestro', 'flow', 'registry', 'get', node_type, '--output', 'json'],
                       capture_output=True, text=True, cwd='/work/output/artifacts/skill-flow-slack-weather-pipeline/SlackWeatherPipeline/SlackWeatherPipeline')
    d = json.loads(r.stdout)
    return d['Data']['Node']

decision_def = get_def('core.logic.decision')
script_def = get_def('core.action.script')
end_def = get_def('core.control.end')

# Remove stale nodes
remove_ids = {'readSlackChannel1', 'fetchWeather1'}
flow['nodes'] = [n for n in flow['nodes'] if n['id'] not in remove_ids]

# Add user-owned nodes
extract_city_script = """
var desc = $vars.getChannelInfo1.output.channel.purpose.value || '';
var parts = desc.split(',').map(function(p){ return p.trim(); }).filter(function(p){ return p.length > 0; });
var city = '';
for (var i = parts.length - 1; i >= 1; i--) {
  var part = parts[i];
  if (/^[A-Z]{2}(\\s+\\d{5}(-\\d{4})?)?$/.test(part)) {
    city = parts[i - 1];
    break;
  }
}
if (!city) { city = parts.length >= 2 ? parts[parts.length - 2] : (parts[0] || ''); }
return { city: city };
"""

flow['nodes'] += [
    {
        "id": "extractCity1",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Extract City from Address"},
        "inputs": {"script": extract_city_script}
    },
    {
        "id": "checkTemperature1",
        "type": "core.logic.decision",
        "typeVersion": "1.1",
        "display": {"label": "Above 60°F?"},
        "inputs": {
            "expression": "$vars.getCurrentWeather1.output.current_weather.temperature > 60",
            "trueLabel": "Warm",
            "falseLabel": "Cold"
        }
    },
    {
        "id": "endWarm",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "Warm Office Today"},
        "inputs": {},
        "outputs": {
            "verdict": {"source": "=js:'warm office today'"}
        }
    },
    {
        "id": "endCold",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "Cold Office Today"},
        "inputs": {},
        "outputs": {
            "verdict": {"source": "=js:'cold office today'"}
        }
    }
]

# Add definitions for user-owned node types
existing_defs = {d['nodeType'] for d in flow['definitions']}
for defn in [script_def, decision_def, end_def]:
    if defn['nodeType'] not in existing_defs:
        flow['definitions'].append(defn)

# Add variables.globals with out variable
flow.setdefault('variables', {})
flow['variables']['globals'] = [
    {
        "id": "verdict",
        "name": "verdict",
        "type": "string",
        "direction": "out",
        "description": "Weather verdict for the office"
    }
]

# Clean variables.nodes: remove stale, add extractCity1 output
flow['variables']['nodes'] = [
    v for v in flow['variables']['nodes']
    if not v.get('binding', {}).get('nodeId') in remove_ids
]
# Add script node output variable
flow['variables']['nodes'].append({
    "id": "extractCity1.output",
    "type": "object",
    "description": "The return value of the script",
    "binding": {"nodeId": "extractCity1", "outputId": "output"}
})

# Set edges
flow['edges'] = [
    {"id": "e-start-getChannelInfo1", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "getChannelInfo1", "targetPort": "input"},
    {"id": "e-getChannelInfo1-extractCity1", "sourceNodeId": "getChannelInfo1", "sourcePort": "output", "targetNodeId": "extractCity1", "targetPort": "input"},
    {"id": "e-extractCity1-geocodeCity1", "sourceNodeId": "extractCity1", "sourcePort": "success", "targetNodeId": "geocodeCity1", "targetPort": "input"},
    {"id": "e-geocodeCity1-getCurrentWeather1", "sourceNodeId": "geocodeCity1", "sourcePort": "default", "targetNodeId": "getCurrentWeather1", "targetPort": "input"},
    {"id": "e-getCurrentWeather1-checkTemperature1", "sourceNodeId": "getCurrentWeather1", "sourcePort": "output", "targetNodeId": "checkTemperature1", "targetPort": "input"},
    {"id": "e-checkTemperature1-endWarm", "sourceNodeId": "checkTemperature1", "sourcePort": "true", "targetNodeId": "endWarm", "targetPort": "input"},
    {"id": "e-checkTemperature1-endCold", "sourceNodeId": "checkTemperature1", "sourcePort": "false", "targetNodeId": "endCold", "targetPort": "input"},
]

# Update layout: remove stale, add new nodes
for nid in remove_ids:
    flow['layout']['nodes'].pop(nid, None)
for nid in ['extractCity1', 'checkTemperature1', 'endWarm', 'endCold']:
    flow['layout']['nodes'][nid] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

with open('/work/output/artifacts/skill-flow-slack-weather-pipeline/SlackWeatherPipeline/SlackWeatherPipeline/SlackWeatherPipeline.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print("FLOW WRITTEN")
print("Nodes:", [n['id'] for n in flow['nodes']])
print("Edges:", [e['id'] for e in flow['edges']])
print("Definitions:", [d['nodeType'] for d in flow['definitions']])
print("Variables globals:", [v['id'] for v in flow.get('variables',{}).get('globals',[])])
PYEOF

